(* [comment removed for export] *)
Lemma pa_fields : forall (M : mem) P p1 p2,
  PML.parser_at M P p1 -> PML.parser_at M P p2 ->
  0 <= PML.ps_level p1 < 2 ^ 32 -> 0 <= PML.ps_level p2 < 2 ^ 32 ->
  Forall (fun x => 0 <= x < 256) (PML.ps_stack p1) -> Forall (fun x => 0 <= x < 256) (PML.ps_stack p2) ->
  (length (PML.ps_stack p1) < 2000)%nat -> (length (PML.ps_stack p2) < 2000)%nat ->
  Z.of_nat (length (PML.ps_buf p1)) < 2 ^ 64 -> Z.of_nat (length (PML.ps_buf p2)) < 2 ^ 64 ->
  PML.ps_done p1 = PML.ps_done p2 /\ PML.ps_more p1 = PML.ps_more p2 /\ PML.ps_level p1 = PML.ps_level p2 /\ PML.ps_stack p1 = PML.ps_stack p2 /\
