Lemma ev_ind_nonneg : forall es ev, 0 <= PMES.ev_ind es ev.
Proof.
  assert (C : forall c, 0 <= PMES.comma c) by (intros c; unfold PMES.comma; destruct (0 <? PMES.ec_count c); lia).
  assert (N : forall es, 1 <= PMES.nl es) by (intros es; unfold PMES.nl, PMES.depth; lia).
  assert (Q : forall es, 0 <= fst (PMES.pre_scalar es)).
  { intros [|c r]; cbn -[PMES.comma PMES.nl]; [lia|]. destruct (PMES.ec_arr c); cbn -[PMES.comma PMES.nl]; [|lia]. pose proof (C c). pose proof (N (c :: r)). lia. }
  assert (U : forall ev, 0 <= PMES.quotes ev) by (intros ev; unfold PMES.quotes; destruct ev; try lia; destruct (_ || _); lia).
  intros es ev. destruct ev; unfold PMES.ev_ind.
  - destruct es as [|c r]; [lia|]. destruct (PMES.ec_arr c); [|lia]. pose proof (C c). pose proof (N (c :: r)). lia.
  - destruct es as [|c r]; [lia|]. destruct (PMES.ec_nla c); unfold PMES.depth; lia.
  - destruct es as [|c r]; [lia|]. pose proof (C c). pose proof (N (c :: r)). lia.
  - pose proof (Q es). pose proof (U (PMES.EvStr tag bs)). lia.
  - pose proof (Q es). pose proof (U PMES.EvNull). lia.
  - pose proof (Q es). pose proof (U (PMES.EvBool b)). lia.
  - pose proof (Q es). pose proof (U PMES.EvU64). lia.
  - pose proof (Q es). pose proof (U PMES.EvI64). lia.
  - pose proof (Q es). pose proof (U PMES.EvDbl). lia.
Qed.
Lemma ind_run_nonneg : forall ks es, 0 <= PMW.ind_run es ks.
Proof.
  induction ks as [|k r IH]; intros es; cbn -[PMW.ind_k PMW.step_k]; [lia|].
  pose proof (ev_ind_nonneg es (PMW.eev_of k)). unfold PMW.ind_k. pose proof (IH (PMW.step_k es k)). lia.
Qed.
Lemma ind_run_le_app : forall es ks1 ks2, PMW.ind_run es ks1 <= PMW.ind_run es (ks1 ++ ks2).
Proof. intros es ks1 ks2. rewrite PMW.ind_run_app. pose proof (ind_run_nonneg ks2 (PMW.es_run es ks1)). lia. Qed.
Lemma wf_stack_nots : forall ps1, PML.wf_ps ps1 -> PML.ps_more ps1 = true -> Forall PMRA.nots (PML.ps_stack ps1).
Proof.
  intros ps1 WF Hm. destruct WF as (_ & _ & _ & _ & C & T & HS & HC & HM). destruct (HM Hm) as (_ & _ & _ & HT & _). rewrite HS. unfold PMRA.nots.
  constructor; [unfold PML.ST_ROOT, PML.ST_STRING, PML.ST_NUMBER; lia|]. apply Forall_app. split.
  - apply Forall_impl with (P := PML.is_container); [|exact HC]. intros a [-> | ->]; unfold PML.ST_OBJECT, PML.ST_ARRAY, PML.ST_STRING, PML.ST_NUMBER; lia.
  - destruct HT as [[-> _] | [[-> _] | [(S & HS1 & -> & _) | (S & HS1 & -> & _)]]];
      repeat first [apply Forall_nil | apply Forall_cons]; try (destruct HS1 as [<-|[<-|[<-|[<-|[<-|[<-|[<-|[]]]]]]]]); cbv; lia.
Qed.
Lemma siq_of_match' : forall c (Mx : mem) Px ps, PMR.rm_match c Mx Px ps -> Forall PMRA.nots (PML.ps_stack ps) -> PMRN.SIq c.
Proof.
  intros c Mx Px ps [CO [HS HN]] HF. apply (PMRN.SIq_intro c ps CO); [|exact HF].
  pose proof CO as (Cst & _). unfold PMRN.tok. rewrite Cst. intros [X|X]; [exact (proj1 (proj2 (HS X))) | exact (proj2 (HN X))].
Qed.
Lemma siq_of_match : forall c (Mx : mem) Px ps, PMR.rm_match c Mx Px ps -> PML.wf_ps ps -> PML.ps_more ps = true -> PMRN.SIq c.
Proof. intros c Mx Px ps H WF Hm. exact (siq_of_match' c Mx Px ps H (wf_stack_nots ps WF Hm)). Qed.
Lemma siq_call : forall a cc b rr0 f c' w', PMR.dispatch (PMR.c_st cc) (PMR.top cc) b = a -> PMRF2.call_of a cc b rr0 = Some (f, c', w') ->
  PMRN.SIq c' -> PMRN.SIq cc.
Proof.
  intros a cc b rr0 f c' w' Hd Hc SI.
  assert (NT : PMRN.tok cc -> a = PMR.AParseString \/ a = PMR.AParseNumber).
  { intros [T|T]; rewrite <- Hd, T; [left; apply PMRF2.dispatch_string | right; apply PMRF2.dispatch_number]. }
  destruct a; cbn [PMRF2.call_of] in Hc; try discriminate Hc; injection Hc as <- <- <-; try exact SI;
    destruct SI as [_ SN]; (split; [intros T; destruct (NT T) as [X|X]; discriminate X|]).
  all: first [ destruct key; cbn [PMRF2.string_entry PMR.tok_clear PMR.set_tok PMR.set_sst PMR.set_st PMR.push PMR.set_stack PMR.c_stack] in SN;
                 [apply Forall_app in SN; exact (proj1 SN) | exact SN]
             | cbn [PMRF2.number_entry PMR.set_nst PMR.set_st PMR.tok1 PMR.tok_clear PMR.set_tok PMR.c_stack] in SN; exact SN ].
Qed.
Lemma end_number_shapeU : forall c w, PMR.q_evs (PMR.end_number c w) = [PMW.EkNum] /\ PMR.q_al (PMR.end_number c w) = PMR.al_num (PMR.c_dlen c) /\
  (PMR.q_code (PMR.end_number c w) = 0 -> PMRA.nots (PMR.c_st (PMR.q_c (PMR.end_number c w)))).
Proof.
  intros c w. unfold PMR.end_number, PMR.bind. cbn -[PMR.after_value]. unfold PMR.after_value. cbv zeta.
  repeat match goal with |- context [if ?b then _ else _] => destruct b end; cbn; (split; [reflexivity|]); (split; [lia|]);
    intros Hc; first [ unfold PMRA.nots; cbv; lia | exfalso; cbv in Hc; lia ].
Qed.

