(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma pst_link : forall i c k ps1 t pv lv pe ce d E1 E' R' (M1 M' : mem) model1 bd stack buf pst,
  is_leaf i c k ps1 t -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) ->
  HAMB i E1 M' model1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
  PSIU.contents I pv pe ce E1 M1 true bd stack buf -> Forall (fun x => 0 <= x <= 255) stack -> (length stack < 2000)%nat ->
  0 <= uv E1 (PB4.pv_level pv) <= 1024 -> PSM2.d_more d = None -> PSM2.d_done d = None ->
  PML.parser_at M' P pst -> PML.wf_ps pst -> PML.ps_more pst = true -> PML.buf_bound pst B -> 0 <= PML.winlen pst ->
  PML.ps_done pst = bd /\ PML.ps_level pst = uv E1 (PB4.pv_level pv) /\ PML.ps_stack pst = stack /\
  PML.ps_sst pst mod 256 = uv E' (PB4.pv_sst lv) mod 256 /\ Z.of_nat (length (PML.ps_buf pst)) = uv E' (PB4.pv_size lv) /\
  (exists bufm, L5.bytes_at RSEGS M' (uv E1 pe) bufm /\ length bufm = length (PML.ps_buf pst) /\ PMR.b256 (PML.ps_buf pst) = PMR.b256 bufm /\
                (PSM2.d_clr d = false -> uv E1 (PB4.pv_st pv) = PML.ST_NUMBER -> PSM2.foot2 c = true -> bufm = buf)) /\
  (PSM2.foot2 c = true -> forall a, 0 <= a < sp - 12800 -> M' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) /\
  uv E' (PB4.pv_st pv) = uv E1 (PB4.pv_st pv) /\ uv E' (PB4.pv_st lv) = match PSM2.d_st d with None => uv E1 (PB4.pv_st pv) | Some e => uv E' e end /\
  uv E' (PB4.pv_sst lv) = PSBU.newv (PSM2.d_sst d) (uv E1 (PB4.pv_sst pv)) /\ uv E' (PB4.pv_nst lv) = PSBU.newv (PSM2.d_nst d) (uv E1 (PB4.pv_nst pv)) /\
  uv E' (PB4.pv_size lv) = (if PSM2.d_clr d then 0 else uv E1 (PB4.pv_size pv)) /\
  uv E' (PB4.pv_wptr lv) = uv E1 (PB4.pv_wptr pv) + PSM2.d_adv d /\ uv E' pe = uv E1 pe /\ uv E' ce = uv E1 ce /\ know_ok RSEGS E' M' (PSM2.lcells ps1) /\ env_agree GT.NF E0 E' /\
  CH2.den E1 (nth i G.BLS []) = [(uv E1 pe, uv E1 ce); (uv E1 (PB4.pv_sb pv), uv E1 (PB4.pv_scend pv) - uv E1 (PB4.pv_sb pv))].
