Definition WCONTY (f : PMW.fname) (j : nat) (pst : PML.pstate) (w' : list Z) (c' : PMR.ctrl) : Prop :=
  WCONT f j pst w' c' /\ (PMRN.SIq c' -> PMW.wroomrU PMR.the_rm eg (PMW.rm_step PMR.the_rm f c' (PMW.inp_win pst w' []))).
Definition eg_adv (evs : list PMW.evk) (al : Z) : PMES.eghost :=
  PMES.EG (PMW.es_run (PMES.g_es eg) evs) (PMES.g_len eg + PMW.ind_run (PMES.g_es eg) evs + al) (PMES.g_rep eg) (PMES.g_sb eg) (PMES.g_scap eg).
Lemma room_whole : PMW.wroomU (PSIU.ieg I) (PMR.q_evs (PMR.parse_some (PSIU.c0 I) (PSIU.w0 I))) (PMR.q_al (PMR.parse_some (PSIU.c0 I) (PSIU.w0 I))).
Proof. exact (PSIU.iHROOM I). Qed.
Lemma hreach_whole : forall c w evs al, PMRF.hreach (PSIU.c0 I) (PSIU.w0 I) c w evs al -> PMRN.SIq c ->
  exists E2 A2, 0 <= A2 /\ PMR.q_evs (PMR.parse_some (PSIU.c0 I) (PSIU.w0 I)) = evs ++ E2 /\ PMR.q_al (PMR.parse_some (PSIU.c0 I) (PSIU.w0 I)) = al + A2.
Proof.
  intros c w evs al [_ H] SI. pose proof (PMRF.phi_nonneg c w) as Hp.
  rewrite (H (S (Z.to_nat (PMRF.phi c w)))) by lia. unfold PMRF.pre. cbn [PMR.q_evs PMR.q_al].
  exists (PMR.q_evs (PMR.loop (S (Z.to_nat (PMRF.phi c w))) c w)), (PMR.q_al (PMR.loop (S (Z.to_nat (PMRF.phi c w))) c w)).
  split; [exact (proj1 (PMRN.loop_alnn _ c w SI)) | split; reflexivity].
Qed.
Lemma room_split : forall evs al E1 A1 E2 A2, PSIU.SYNC I eg evs al -> PMW.wroomU (PSIU.ieg I) (evs ++ E1 ++ E2) (al + (A1 + A2)) -> 0 <= A2 ->
  PMW.wroomU eg E1 A1.
Proof.
  intros evs al E1 A1 E2 A2 [Hes [pay [Hp Hlen]]] H HA2.
  exact (PMW.wroomU_app eg E1 E2 A1 A2 (PMW.wroomU_shift (PSIU.ieg I) eg evs (E1 ++ E2) al (A1 + A2) pay H Hes Hlen Hp) (ind_run_nonneg _ _) HA2).
Qed.
Lemma room_split0 : forall evs al E1 A1, PSIU.SYNC I eg evs al -> PMW.wroomU (PSIU.ieg I) (evs ++ E1) (al + A1) -> PMW.wroomU eg E1 A1.
Proof. intros evs al E1 A1 HS H. apply (room_split evs al E1 A1 [] 0 HS); [rewrite app_nil_r, Z.add_0_r; exact H | lia]. Qed.
Lemma wcont_room_of_call : forall j a cc b rr0 evs al f c' w' pst p',
  PMRF.hreach (PSIU.c0 I) (PSIU.w0 I) cc (b :: rr0) evs al -> PSIU.SYNC I eg evs al -> PMR.c_more cc = true ->
  PMR.dispatch (PMR.c_st cc) (PMR.top cc) b = a -> PMRF2.call_of a cc b rr0 = Some (f, c', w') ->
  PML.ps_win pst = PB4.win_of p' wend -> seg <= p' <= wend -> w' = skipn (Z.to_nat (p' - seg)) (PSIU.w0 I) ->
  PSIU.PTOFF j = PSYJK.ptoff_of a -> (a = PMR.AComma -> b :: rr0 = skipn (Z.to_nat (p' - seg)) (PSIU.w0 I)) ->
  PMRN.SIq c' -> PMW.wroomrU PMR.the_rm eg (PMW.rm_step PMR.the_rm f c' (PMW.inp_win pst w' [])).
Proof.
  intros j a cc b rr0 evs al f c' w' pst p' HR HS Hm Hd Hc _ _ _ _ _ SI.
  pose proof (siq_call a cc b rr0 f c' w' Hd Hc SI) as SIc.
  pose proof (PMRN.iter_alnn cc b rr0 SIc Hm) as [_ SIit].
  pose proof room_whole as HR0. destruct HR as [_ HR].
  pose proof (PMRF.phi_nonneg cc (b :: rr0)) as Hph.
  rewrite (HR (S (Z.to_nat (PMRF.phi cc (b :: rr0))))) in HR0 by lia.
  rewrite (PMRF.loop_step _ cc b rr0 Hm) in HR0. unfold PMRF.pre in HR0. cbn [PMR.q_evs PMR.q_al] in HR0.
  change (PMW.wroomU eg (PMW.r_evs (PMR.rstep f c' w')) (PMW.r_allow (PMR.rstep f c' w'))).
  rewrite (PMRF2.rstep_fcall f c' w' (proj1 (PMRF2.call_of_win a cc b rr0 f c' w' Hc))), PMRF2.r_of_evs, PMRF2.r_of_allow.
  assert (HIT : PMR.iter cc b rr0 = PMRF2.fcall f c' w' \/ PMR.iter cc b rr0 = PMR.bind (PMRF2.fcall f c' w') (fun c1 _ => PMR.ret c1 rr0)).
  { unfold PMR.iter. rewrite Hd. destruct a; try (left; exact (PMRF2.iter_call _ _ _ _ _ _ _ Hc ltac:(discriminate))).
    right. cbn [PMRF2.call_of] in Hc. injection Hc as <- <- <-. reflexivity. }
  set (R := PMRF2.fcall f c' w') in *. set (F' := Z.to_nat (PMRF.phi cc (b :: rr0))) in *.
  destruct (Z.eq_dec (PMR.q_code R) 0) as [Rok|Rerr].
  - assert (HE : PMR.q_code (PMR.iter cc b rr0) = 0 /\ PMR.q_evs (PMR.iter cc b rr0) = PMR.q_evs R /\ PMR.q_al (PMR.iter cc b rr0) = PMR.q_al R).
    { destruct HIT as [-> | ->]; [repeat split; auto|]. rewrite (PMRF.bind_ok R _ Rok). unfold PMRF.pre, PMR.ret. cbn [PMR.q_code PMR.q_evs PMR.q_al].
      rewrite app_nil_r. repeat split; try reflexivity; lia. }
    destruct HE as (Hc0 & HE1 & HA1). rewrite (PMRF.bind_ok _ _ Hc0) in HR0. unfold PMRF.pre in HR0. cbn [PMR.q_evs PMR.q_al] in HR0.
    rewrite HE1, HA1 in HR0. exact (room_split evs al _ _ _ _ HS HR0 (proj1 (PMRN.loop_alnn _ _ _ SIit))).
  - assert (HE : PMR.bind (PMR.iter cc b rr0) (PMR.loop F') = R).
    { destruct HIT as [-> | ->]; [exact (PMRF.bind_err R _ Rerr)|]. rewrite (PMRF.bind_err R _ Rerr). exact (PMRF.bind_err R _ Rerr). }
    rewrite HE in HR0. exact (room_split0 evs al _ _ HS HR0).
Qed.
Lemma wconty_of_call : forall j a cc b rr0 evs al f c' w' pst p',
  PMRF.hreach (PSIU.c0 I) (PSIU.w0 I) cc (b :: rr0) evs al -> PSIU.SYNC I eg evs al -> PMR.c_more cc = true ->
  PMR.dispatch (PMR.c_st cc) (PMR.top cc) b = a -> PMRF2.call_of a cc b rr0 = Some (f, c', w') ->
  PML.ps_win pst = PB4.win_of p' wend -> seg <= p' <= wend -> w' = skipn (Z.to_nat (p' - seg)) (PSIU.w0 I) ->
  PSIU.PTOFF j = PSYJK.ptoff_of a -> (a = PMR.AComma -> b :: rr0 = skipn (Z.to_nat (p' - seg)) (PSIU.w0 I)) ->
  WCONTY f j pst w' c'.
Proof.
  intros j a cc b rr0 evs al f c' w' pst p' H1 H2 H3 H4 H5 H6 H7 H8 H9 H10. split.
  - exact (wcont_of_call j a cc b rr0 evs al f c' w' pst p' H1 H2 H3 H4 H5 H6 H7 H8 H9 H10).
  - intros SI. exact (wcont_room_of_call j a cc b rr0 evs al f c' w' pst p' H1 H2 H3 H4 H5 H6 H7 H8 H9 H10 SI).
Qed.
Lemma room_arith1 : forall gl ir pay al clu lhs : Z, lhs = gl + ir + pay -> 0 <= pay <= al -> gl + ir + al <= clu -> lhs <= clu.
Proof. intros. lia. Qed.
Lemma room_arith2 : forall gl ir1 ir2 pay al A2 clu lhs : Z, lhs = gl + ir1 + pay -> 0 <= pay <= al -> gl + ir2 + (al + A2) <= clu -> ir1 <= ir2 -> 0 <= A2 -> lhs <= clu.
Proof. intros. lia. Qed.
Lemma room_of_ptw : forall E A j ps2 code (M2 : mem), 0 <= A -> Forall PMRA.nots (PML.ps_stack ps2) -> PSIU.PTW I (eg_adv E A) j ps2 code M2 ->
  PMW.wroomU eg E A.
Proof.
  intros E A j ps2 code M2 HA HN (evs & al & q & Hq & [_ [pay [Hp Hlen]]] & Herr & Hok).
  unfold eg_adv in Hlen. cbn [PMES.g_len] in Hlen.
  pose proof room_whole as HR0. unfold PMW.wroomU in *.
  destruct (Z.eq_dec code 0) as [C0|Cn].
  - destruct (Hok C0) as (HM & HH & _). destruct (hreach_whole _ _ _ _ HH (siq_of_match' _ _ _ _ HM HN)) as (E2 & A2 & HA2 & HE & HAl).
    rewrite HE, HAl in HR0. pose proof (ind_run_le_app (PMES.g_es (PSIU.ieg I)) (evs ++ PMR.q_evs q) E2) as HLE.
    exact (room_arith2 _ _ _ _ _ _ _ _ Hlen Hp HR0 HLE HA2).
  - rewrite (Herr Cn) in HR0. unfold PMRF.pre in HR0. cbn [PMR.q_evs PMR.q_al] in HR0. exact (room_arith1 _ _ _ _ _ _ Hlen Hp HR0).
Qed.
Lemma fname_endnum : forall pc, pc = PML.PC_END_INT \/ pc = PML.PC_END_FRAC -> fname_of pc = PMW.FEndInt \/ fname_of pc = PMW.FEndFrac.
Proof. intros pc [-> | ->]; first [left; vm_compute; reflexivity | right; vm_compute; reflexivity]. Qed.

