(* [comment removed for export] *)
Lemma callw_head : forall i c k ps1 pc x j pv lv pe ce d E1 E' R' (M1 M' : mem) model1 pst,
  is_leaf i c k ps1 (CC.TOther pc) -> CH2.ret_of G.RETS i k = Some j -> pt_of pc = Some x ->
  PSCW.lact i k = None -> PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) -> kind_of i = KInv -> i <> I_ENTRY ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> HAMB i E1 M' model1 ->
  SIM i E1 M1 -> XI i E1 M1 ->
  PML.parser_at M' P pst -> PML.wf_ps pst -> PML.ps_more pst = true -> PML.buf_bound pst B ->
