(* [comment removed for export] *)
Definition WCONTB (f : PMW.fname) (j : nat) (pst : PML.pstate) (c' : PMR.ctrl) : Prop :=
  forall (eg' : PMES.eghost) (M2 : mem) (ps2 : PML.pstate) (code : Z),
    let rr := PMR.rstep f c' (PML.ps_buf pst) in
    code = PMW.r_code rr ->
    (PMES.g_es eg' = PMW.es_run (PMES.g_es eg) (PMW.r_evs rr) /\
      exists pay, 0 <= pay <= PMW.r_allow rr /\ PMES.g_len eg' = PMES.g_len eg + PMW.ind_run (PMES.g_es eg) (PMW.r_evs rr) + pay) ->
    (code = 0 -> PMR.rm_match (PMW.r_ctrl rr) M2 P ps2 /\ PMW.r_used rr = PML.winlen pst - PML.winlen ps2 /\ snd (PSA.wincells (PML.ps_win ps2)) = wend) ->
    PSIU.PTW I eg' j ps2 code M2.
Definition WCONTBY (f : PMW.fname) (j : nat) (pst : PML.pstate) (c' : PMR.ctrl) : Prop :=
  WCONTB f j pst c' /\ (PMRN.SIq c' -> PMW.wroomrU PMR.the_rm eg (PMW.rm_step PMR.the_rm f c' (PMW.inp_buf pst [] []))).
Definition ps_after (c : PMR.ctrl) (pst : PML.pstate) : PML.pstate :=
  PML.PS (PMR.c_st c) (PML.ps_sst pst) (PML.ps_nst pst) (PMR.c_more c) (PMR.c_done c) (PMR.c_level c) (PMR.c_stack c) (PML.ps_sb pst) (PML.ps_scap pst)
         (PML.ps_bcap pst) (PML.ps_bptr pst) (PML.ps_buf pst) (Some (wend - PML.winlen pst, wend)).
Lemma winlen_after : forall c pst, PML.winlen (ps_after c pst) = PML.winlen pst.
Proof.
  intros c pst. assert (H : PML.ps_win (ps_after c pst) = Some (wend - PML.winlen pst, wend)) by reflexivity.
  unfold PML.winlen at 1. rewrite H. cbv beta iota. lia.
Qed.
Lemma room_endnum : forall f j pst c' (Mx : mem), WCONTB f j pst c' -> (f = PMW.FEndInt \/ f = PMW.FEndFrac) -> PMRN.SIq c' ->
  PMW.wroomrU PMR.the_rm eg (PMW.rm_step PMR.the_rm f c' (PMW.inp_buf pst [] [])).
Proof.
  intros f j pst c' Mx HB Hf SI.
  assert (Hrr : PMR.rstep f c' (PML.ps_buf pst) = PMR.r_of0 (PMR.end_number (PMR.of_text c' (PML.ps_buf pst)) [])) by (destruct Hf as [-> | ->]; reflexivity).
  change (PMW.wroomU eg (PMW.r_evs (PMR.rstep f c' (PML.ps_buf pst))) (PMW.r_allow (PMR.rstep f c' (PML.ps_buf pst)))).
  rewrite Hrr. cbn [PMR.r_of0 PMW.r_evs PMW.r_allow].
  destruct (end_number_shapeU (PMR.of_text c' (PML.ps_buf pst)) []) as (_ & HAl & HOk).
  set (q := PMR.end_number (PMR.of_text c' (PML.ps_buf pst)) []) in *.
  assert (Hal : 0 <= PMR.q_al q) by (rewrite HAl; unfold PMR.al_num; cbn [PMR.c_dlen PMR.of_text PMR.set_tok]; lia).
  assert (HN : Forall PMRA.nots (PML.ps_stack (ps_after (PMR.q_c q) pst))) by (cbn [ps_after PML.ps_stack]; unfold q; rewrite PMRF.end_number_stack; exact (proj2 SI)).
  apply (room_of_ptw (PMR.q_evs q) (PMR.q_al q) j (ps_after (PMR.q_c q) pst) (PMR.q_code q) Mx Hal HN).
  pose proof (HB (eg_adv (PMR.q_evs q) (PMR.q_al q)) Mx (ps_after (PMR.q_c q) pst) (PMR.q_code q)) as HB'. cbv zeta in HB'. rewrite Hrr in HB'.
  cbn [PMR.r_of0 PMW.r_evs PMW.r_allow PMW.r_code PMW.r_ctrl PMW.r_used] in HB'. apply HB'; [reflexivity | |].
  - split; [reflexivity|]. exists (PMR.q_al q). split; [lia | reflexivity].
  - intros C0. pose proof (HOk C0) as NS. split; [|split].
    + refine (conj (conj eq_refl (conj eq_refl (conj eq_refl (conj eq_refl eq_refl)))) (conj _ _)); cbn [ps_after PML.ps_st]; intros X;
        [exact (False_ind _ (proj1 NS X)) | exact (False_ind _ (proj2 NS X))].
    + rewrite winlen_after. lia.
    + reflexivity.
Qed.

