  SIM I_ENTRY E1 M1 -> XI I_ENTRY E1 M1 ->
  PML.parser_at M' P pst -> PML.wf_ps pst -> PML.ps_more pst = true -> PML.buf_bound pst B ->
  PML.ps_st pst = uv E' (PB4.pv_st lv) -> PML.ps_nst pst = uv E' (PB4.pv_nst lv) -> PML.ps_win pst = PB4.win_of (uv E' (PB4.pv_wptr lv)) wend -> seg <= uv E' (PB4.pv_wptr lv) <= wend ->
  exists w' c', PMW.win_bytes M' pst w' /\ PMR.rm_match c' M' P pst /\ WCONTBY (fname_of pc) j pst c' /\ (pc = PML.PC_END_INT \/ pc = PML.PC_END_FRAC).
Proof.
  intros c k ps1 pc x j pv lv pe ce d E1 E' R' M1 M' model1 pst H1 H2 H3 H4 H5 H6 H7 H8 H9 H10 H11 H12 H13 H14 H15 H16 H17 H18.
  destruct (callw_entry0 c k ps1 pc x j pv lv pe ce d E1 E' R' M1 M' model1 pst H1 H2 H3 H4 H5 H6 H7 H8 H9 H10 H11 H12 H13 H14 H15 H16 H17 H18)
    as (w' & c' & HWB & HRM & HB & Hpc).
  exists w', c'. split; [exact HWB|]. split; [exact HRM|]. split; [|exact Hpc]. split; [exact HB|].
  intros SI. exact (room_endnum (fname_of pc) j pst c' M' HB (fname_endnum pc Hpc) SI).
Qed.

