Lemma callw : forall i c k ps1 pc x j pv lv pe ce d E1 E' R' (M1 M' : mem) model1 pst,
  is_leaf i c k ps1 (CC.TOther pc) -> CH2.ret_of G.RETS i k = Some j -> pt_of pc = Some x -> SR.ps_pc ps1 = pc ->
  PSM2.ldelta i c ps1 = Some (pv, lv, pe, ce, d) ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> HAMB i E1 M' model1 ->
  SIM i E1 M1 -> XI i E1 M1 ->
  PML.parser_at M' P pst -> PML.wf_ps pst -> PML.ps_more pst = true -> PML.buf_bound pst B ->
  PML.ps_st pst = uv E' (PB4.pv_st lv) -> PML.ps_nst pst = uv E' (PB4.pv_nst lv) -> PML.ps_win pst = PB4.win_of (uv E' (PB4.pv_wptr lv)) wend -> seg <= uv E' (PB4.pv_wptr lv) <= wend ->
  exists w' c', PMW.win_bytes M' pst w' /\ PMR.rm_match c' M' P pst /\
